package dev.studyforge.banking.application; import dev.studyforge.banking.domain.*; import java.util.*; public final class TransferService{private final UnitOfWork uow;private final TransactionFactory factory;private final FeeStrategy fee;private final List<NotificationPort> notifications;public TransferService(UnitOfWork u,TransactionFactory f,FeeStrategy fee,List<NotificationPort> n){uow=u;factory=f;this.fee=fee;notifications=List.copyOf(n);}public Transaction transfer(Transfer c){if(c.source().equals(c.destination()))throw new InvalidBankingOperationException("Source and destination must differ");Money f=fee.calculate(c.amount());Transaction tx=factory.transfer(c.source(),c.destination(),c.amount(),f);Transaction done=uow.execute((a,t)->{Account source=a.findById(c.source()).orElseThrow(()->new AccountNotFoundException(c.source()));Account dest=a.findById(c.destination()).orElseThrow(()->new AccountNotFoundException(c.destination()));a.save(source.debit(c.amount().add(f)));a.save(dest.credit(c.amount()));t.save(tx);return tx;});for(NotificationPort n:notifications)try{n.transactionCompleted(done);}catch(RuntimeException e){throw new NotificationDeliveryException(done,e);}return done;}}
